func isDirty(repoPath string) (bool, error) {
	out, err := run(repoPath, "", "status", "--porcelain")
	if err != nil {
		return false, err
	}
	return strings.TrimSpace(out) != "", nil
}

// run executes one git command in a repository and returns its stdout.
//
// It carries the same non-interactive environment as Clone. A `git fetch` is a
// network call like any other, and left to itself it reaches the credential
// helper — which on Windows writes to the console over the rendered frame and
// then waits on a browser. That was §3.16's observed failure, and nothing about
// it was specific to cloning.
func run(repoPath, token string, args ...string) (string, error) {
	return runContext(context.Background(), repoPath, token, args...)
}

// runContext is run with a context, so a long fetch can be abandoned.
func runContext(ctx context.Context, repoPath, token string, args ...string) (string, error) {
	return runContextMax(ctx, repoPath, token, 0, args...)
}

// ErrOutputTooLarge is returned when a command wrote more than it was allowed.
var ErrOutputTooLarge = errors.New("output is larger than allowed")

// capWriter collects output up to max bytes (no limit when max is 0) and fails
// the write past it, which makes the child's stdout copy fail and stops the
// process instead of buffering whatever it wants to say.
type capWriter struct {
	buf      strings.Builder
	max      int64
	exceeded bool
}

func (w *capWriter) Write(p []byte) (int, error) {
	if w.max > 0 && int64(w.buf.Len()+len(p)) > w.max {
		w.exceeded = true
		return 0, ErrOutputTooLarge
	}
	return w.buf.Write(p)
}

// hardening is the configuration every command runs with, ahead of its own
// arguments: the repository is not trusted, and its .git/config or hooks must
// not make a read run a program of its choosing (DEVDESK-753). A -c option wins
// over every configuration file. /dev/null also works for git on Windows, which
// maps it itself.
//
// It stops the two hooks a status or a fetch reaches without any user action,
// the file system monitor and the repository's hooks. Other settings that name
// a program (a filter driver, an external diff) are not covered.
func hardening() []string {
	return []string{"-c", "core.fsmonitor=false", "-c", "core.hooksPath=" + os.DevNull}
}

// runContextMax is runContext with a ceiling on what stdout may hold.
func runContextMax(ctx context.Context, repoPath, token string, max int64, args ...string) (string, error) {
	cmd := exec.CommandContext(ctx, "git", append(hardening(), args...)...)
	cmd.Dir = repoPath
	cmd.Env = append(nonInteractiveEnv(token),
		// A read must not take the index lock: it would make a concurrent
		// git of the user fail for no reason.
		"GIT_OPTIONAL_LOCKS=0",
	)

	stdout := &capWriter{max: max}
	var stderr strings.Builder
	cmd.Stdin = nil
	cmd.Stdout = stdout
	cmd.Stderr = &stderr

	if err := cmd.Run(); err != nil {
		if ctx.Err() != nil {
			return "", ctx.Err()
		}
		// The process may die of the broken pipe before Run reports the write
		// error, so the flag is the reliable signal.
		if stdout.exceeded {
			return "", ErrOutputTooLarge
		}
		if reason := lastLine(stderr.String()); reason != "" {
			return "", fmt.Errorf("%s", reason)
		}
		return "", err
	}
	return stdout.buf.String(), nil
}
